#!/bin/bash
# The selected recipe (frontier_window W=512 centered, hard K=256) trained with rank-16
# LoRA on every block up to the read layer, one run per depth and seed on Apertus-8B-Instruct.
# Same step budget and checkpoint cadence as the frozen sweep, no early stopping; the whole
# validation split is monitored, since an adapted run cannot be replayed afterwards.
set -euo pipefail
cd /iopsstor/scratch/cscs/mdenegri/degeneration-probe

